                        var keyEvent = new KeyEventArgs()
                        {
                            KeyModifiers = (KeyModifiers)rawKeyEventArgs.Modifiers,
                            Key = rawKeyEventArgs.Key,
                            PhysicalKey = rawKeyEventArgs.PhysicalKey,
                            KeyDeviceType = rawKeyEventArgs.KeyDeviceType,
